param(
    [string]$ProjectRoot = "",
    [switch]$DryRun,
    [switch]$SkipInitialBuild,
    [switch]$SkipFinalBuild,
    [switch]$SkipLint
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
$env:GIT_PAGER = "cat"
try {
    [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding($false)
    $OutputEncoding = New-Object System.Text.UTF8Encoding($false)
} catch {}

$Utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$Marker = "ORCALY_OWNER_BACKOFFICE_V2"
$GuardedTextPatches = @(
    [pscustomobject]@{ Path = "app/api/admin/affiliates/route.ts"; ExpectedHeadBlob = "d3481e7548dcedd86fac4456a35f0e8440de6b03" },
    [pscustomobject]@{ Path = "app/api/platform-admin/summary/route.ts"; ExpectedHeadBlob = "b43f15c4611581f9130838e7091d69d18a1ea547" }
)
if ([string]::IsNullOrWhiteSpace($ProjectRoot)) { $ProjectRoot = (Get-Location).Path } else { $ProjectRoot = (Resolve-Path -LiteralPath $ProjectRoot).Path }
$Timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$BackupRoot = Join-Path $ProjectRoot (".orcaly-backups\owner-backoffice-" + $Timestamp)
$LogPath = Join-Path $BackupRoot "execucao.log"
$ReportPath = Join-Path $BackupRoot "RELATORIO-OWNER-BACKOFFICE.md"
$ManifestPath = Join-Path $BackupRoot "manifesto-arquivos.txt"
$ChangedFiles = New-Object System.Collections.Generic.List[string]
$BackupMap = @{}
$InitialBuildPassed = $null
$InitialLintPassed = $null
$Specs = New-Object System.Collections.Generic.List[object]

function Write-Step([string]$Text) { Write-Host ""; Write-Host ("==> " + $Text) -ForegroundColor Cyan; if (-not $DryRun -and (Test-Path $BackupRoot)) { [IO.File]::AppendAllText($LogPath, ("[" + (Get-Date -Format "yyyy-MM-dd HH:mm:ss") + "] " + $Text + [Environment]::NewLine), $Utf8NoBom) } }
function Write-Ok([string]$Text) { Write-Host ("[OK] " + $Text) -ForegroundColor Green }
function Write-Warn([string]$Text) { Write-Host ("[AVISO] " + $Text) -ForegroundColor Yellow }
function Normalize([string]$Path) { return (($Path -replace "\\", "/").Trim()) }
function Get-Sha([string]$Path) { if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return "" }; return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant() }
function Get-HeadBlob([string]$Relative) { $value = @(& git rev-parse ("HEAD:" + (Normalize $Relative)) 2>$null); if ($LASTEXITCODE -ne 0) { return "" }; return (($value -join "`n").Trim()) }
function Is-WorkingTreeCleanFor([string]$Relative) { & git diff --quiet -- $Relative; $work = $LASTEXITCODE; & git diff --cached --quiet -- $Relative; $stage = $LASTEXITCODE; return ($work -eq 0 -and $stage -eq 0) }
function Backup-File([string]$Relative) { if ($DryRun) { return }; $src = Join-Path $ProjectRoot ($Relative -replace "/", "\"); if (-not (Test-Path $src -PathType Leaf)) { return }; if ($BackupMap.ContainsKey($Relative)) { return }; $dst = Join-Path $BackupRoot ($Relative -replace "/", "\"); [IO.Directory]::CreateDirectory((Split-Path -Parent $dst)) | Out-Null; Copy-Item -LiteralPath $src -Destination $dst -Force; $BackupMap[$Relative] = $dst }
function Restore-Files { if ($DryRun) { return }; foreach ($relative in @($ChangedFiles)) { $target = Join-Path $ProjectRoot ($relative -replace "/", "\"); if ($BackupMap.ContainsKey($relative)) { Copy-Item -LiteralPath $BackupMap[$relative] -Destination $target -Force; Write-Warn ("Restaurado: " + $relative) } elseif (Test-Path $target) { Remove-Item -LiteralPath $target -Force; Write-Warn ("Removido arquivo criado: " + $relative) } } }
function Run-Npm {
    param(
        [Parameter(Mandatory = $true)]
        [string]$Label,

        [Parameter(Mandatory = $true)]
        [string[]]$CommandArgs
    )

    Write-Step $Label

    $safeArgs = @(
        $CommandArgs |
            ForEach-Object { [string]$_ } |
            Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
    )

    if ($safeArgs.Count -eq 0) {
        throw "Nenhum argumento npm foi informado para '$Label'."
    }

    if (-not (Get-Command npm.cmd -ErrorAction SilentlyContinue)) {
        throw "npm.cmd não foi encontrado no PATH."
    }

    $dir = Join-Path $BackupRoot ("comandos\" + ($Label -replace "[^A-Za-z0-9_-]", "-"))
    [IO.Directory]::CreateDirectory($dir) | Out-Null

    $stdoutPath = Join-Path $dir "stdout.log"
    $stderrPath = Join-Path $dir "stderr.log"

    $process = Start-Process `
        -FilePath "npm.cmd" `
        -ArgumentList $safeArgs `
        -WorkingDirectory $ProjectRoot `
        -Wait `
        -PassThru `
        -NoNewWindow `
        -RedirectStandardOutput $stdoutPath `
        -RedirectStandardError $stderrPath

    if (Test-Path -LiteralPath $stdoutPath) {
        Get-Content -LiteralPath $stdoutPath |
            ForEach-Object { Write-Host $_ }
    }

    if (Test-Path -LiteralPath $stderrPath) {
        Get-Content -LiteralPath $stderrPath |
            ForEach-Object { Write-Host $_ }
    }

    return ($process.ExitCode -eq 0)
}
function Write-Report([System.Collections.IEnumerable]$Specs, [string]$Status) { if ($DryRun) { return }; $lines = New-Object System.Collections.Generic.List[string]; $lines.Add("# Orçaly - Owner Backoffice V2"); $lines.Add(""); $lines.Add("Status: " + $Status); $lines.Add("Data: " + (Get-Date -Format "dd/MM/yyyy HH:mm:ss")); $lines.Add("Branch: " + ((& git branch --show-current | Out-String).Trim())); $lines.Add(""); $lines.Add("## Objetivo"); $lines.Add("- /admin completo exclusivo de viniciusadm@orcaly.com."); $lines.Add("- Login interno unificado em /parceiros/login."); $lines.Add("- Controle de assinantes, indicadores, Pix/repasses, suporte e auditoria."); $lines.Add("- /suporte separado, sem valores financeiros, Pix, repasses, equipe ou auditoria."); $lines.Add("- APIs administrativas legadas de resumo e indicadores ficam owner-only para impedir bypass do suporte."); $lines.Add(""); $lines.Add("## Arquivos do escopo"); foreach ($s in $Specs) { $lines.Add("- " + $s.path) }; $lines.Add(""); $lines.Add("## Arquivos alterados"); if ($ChangedFiles.Count -eq 0) { $lines.Add("- Nenhum") } else { foreach ($f in $ChangedFiles) { $lines.Add("- " + $f) } }; $lines.Add(""); $lines.Add("## Segurança"); $lines.Add("- Owner validado por role ativa + e-mail exato no servidor e no proxy."); $lines.Add("- Chave Pix completa continua server-side e auditada pela API existente."); $lines.Add("- Nenhuma migration/RLS/Supabase é alterado por este script."); $lines.Add("- Nenhum commit, push ou deploy é executado."); [IO.File]::WriteAllText($ReportPath, (($lines -join [Environment]::NewLine) + [Environment]::NewLine), $Utf8NoBom) }

function Apply-GuardedLegacyApiPatches {
    $affPath = Join-Path $ProjectRoot "app\api\admin\affiliates\route.ts"
    $aff = [IO.File]::ReadAllText($affPath)
    if (-not $aff.Contains($Marker)) {
        Backup-File "app/api/admin/affiliates/route.ts"
        if ($aff -notmatch "requireOfficialPlatformOwner") {
            $aff = $aff -replace "platformCapabilities,\s*requirePlatformAdmin,", "platformCapabilities,`n  requireOfficialPlatformOwner,`n  requirePlatformAdmin,"
        }
        $pattern = "const session = await requirePlatformAdmin\(\s*request,\s*'affiliates\.view',\s*\)"
        $updated = [regex]::Replace($aff, $pattern, "const session = await requireOfficialPlatformOwner(request)", 1)
        if ($updated -eq $aff -or $updated -notmatch "requireOfficialPlatformOwner\(request\)") { throw "Não foi possível endurecer GET /api/admin/affiliates sem reescrever o arquivo." }
        $updated = $updated -replace "// ORCALY_OWNER_SUPPORT_CONTROL_V1", "// ORCALY_OWNER_SUPPORT_CONTROL_V1`n// ORCALY_OWNER_BACKOFFICE_V2"
        [IO.File]::WriteAllText($affPath, $updated, $Utf8NoBom)
        if (-not $ChangedFiles.Contains("app/api/admin/affiliates/route.ts")) { $ChangedFiles.Add("app/api/admin/affiliates/route.ts") }
        Write-Ok "API de indicadores: leitura completa tornou-se owner-only."
    }

    $summaryPath = Join-Path $ProjectRoot "app\api\platform-admin\summary\route.ts"
    $summary = [IO.File]::ReadAllText($summaryPath)
    if (-not $summary.Contains($Marker)) {
        Backup-File "app/api/platform-admin/summary/route.ts"
        if ($summary -notmatch "requireOfficialPlatformOwner") {
            $summary = $summary -replace "canPlatform,\s*requirePlatformAdmin,", "canPlatform,`n  requireOfficialPlatformOwner,"
        }
        $pattern = "const auth = await requirePlatformAdmin\(\s*request,\s*'dashboard\.view',\s*\)"
        $updated = [regex]::Replace($summary, $pattern, "const auth = await requireOfficialPlatformOwner(request)", 1)
        if ($updated -eq $summary -or $updated -notmatch "requireOfficialPlatformOwner\(request\)") { throw "Não foi possível endurecer /api/platform-admin/summary sem reescrever o arquivo." }
        $updated = $updated -replace "// ORCALY_OWNER_SUPPORT_CONTROL_V1", "// ORCALY_OWNER_SUPPORT_CONTROL_V1`n// ORCALY_OWNER_BACKOFFICE_V2"
        [IO.File]::WriteAllText($summaryPath, $updated, $Utf8NoBom)
        if (-not $ChangedFiles.Contains("app/api/platform-admin/summary/route.ts")) { $ChangedFiles.Add("app/api/platform-admin/summary/route.ts") }
        Write-Ok "Resumo legado da plataforma tornou-se owner-only."
    }
}


try {
    Write-Host ""; Write-Host "ORÇALY - OWNER BACKOFFICE V3" -ForegroundColor Cyan; Write-Host "Compatível com Windows PowerShell 5.1: audita, preserva e só então aplica." -ForegroundColor DarkCyan
    if (-not (Test-Path (Join-Path $ProjectRoot "package.json") -PathType Leaf)) { throw "Execute na raiz do projeto Orçaly." }
    if (-not (Test-Path (Join-Path $ProjectRoot ".git") -PathType Container)) { throw "A pasta não é o repositório Git esperado." }
    Set-Location $ProjectRoot
    $json = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
    $decodedSpecs = ConvertFrom-Json -InputObject $json
    $Specs = New-Object System.Collections.Generic.List[object]

    foreach ($decodedSpec in $decodedSpecs) {
        $Specs.Add($decodedSpec)
    }

    if ($Specs.Count -eq 0) {
        throw "O manifesto interno do patch está vazio."
    }

    Write-Ok ("Manifesto interno carregado corretamente: " + $Specs.Count + " arquivo(s).")
    if (-not $DryRun) { [IO.Directory]::CreateDirectory($BackupRoot) | Out-Null }

    Write-Step "Auditando branch e arquivos locais"
    Write-Host ("Branch: " + ((& git branch --show-current | Out-String).Trim()))
    & git status --short
    $Blocked = New-Object System.Collections.Generic.List[string]
    foreach ($s in $Specs) {
        $relative = Normalize $s.path
        $full = Join-Path $ProjectRoot ($relative -replace "/", "\")
        $exists = Test-Path $full -PathType Leaf
        $currentSha = if ($exists) { Get-Sha $full } else { "" }
        if ($exists -and $currentSha -eq [string]$s.sha256) { Write-Ok ($relative + " já está na versão V2"); continue }
        if ([bool]$s.new_file) { if ($exists) { $Blocked.Add($relative + " já existe com conteúdo diferente.") } else { Write-Ok ($relative + " será criado.") }; continue }
        if (-not $exists) { $Blocked.Add($relative + " não foi encontrado."); continue }
        if (-not (Is-WorkingTreeCleanFor $relative)) { $Blocked.Add($relative + " possui alteração local/staged. O patch não vai sobrescrever."); continue }
        $headBlob = Get-HeadBlob $relative
        if ($headBlob -ne [string]$s.expected_head_blob) { $Blocked.Add($relative + " está em outra versão no HEAD (esperado " + [string]$s.expected_head_blob + ", atual " + $headBlob + ").") } else { Write-Ok ($relative + " corresponde à versão auditada.") }
    }
    foreach ($g in $GuardedTextPatches) {
        $relative = Normalize $g.Path
        $full = Join-Path $ProjectRoot ($relative -replace "/", "\")
        if (-not (Test-Path $full -PathType Leaf)) { $Blocked.Add($relative + " não foi encontrado."); continue }
        $text = [IO.File]::ReadAllText($full)
        if ($text.Contains($Marker)) { Write-Ok ($relative + " já está protegido pela V2"); continue }
        if (-not (Is-WorkingTreeCleanFor $relative)) { $Blocked.Add($relative + " possui alteração local/staged. O patch não vai sobrescrever."); continue }
        $headBlob = Get-HeadBlob $relative
        if ($headBlob -ne [string]$g.ExpectedHeadBlob) { $Blocked.Add($relative + " está em outra versão no HEAD (esperado " + [string]$g.ExpectedHeadBlob + ", atual " + $headBlob + ").") } else { Write-Ok ($relative + " corresponde à versão auditada.") }
    }

    if ($Blocked.Count -gt 0) { Write-Host ""; Write-Host "Patch bloqueado para preservar o projeto:" -ForegroundColor Red; foreach ($b in $Blocked) { Write-Host ("  - " + $b) }; throw "A auditoria encontrou arquivos que não podem ser sobrescritos com segurança." }

    $pkg = Get-Content (Join-Path $ProjectRoot "package.json") -Raw | ConvertFrom-Json
    $scripts = @(); if ($pkg.scripts) { $scripts = @($pkg.scripts.PSObject.Properties | ForEach-Object { $_.Name }) }
    if (-not $DryRun -and -not $SkipInitialBuild -and ("build" -in $scripts)) { $InitialBuildPassed = Run-Npm -Label "build-inicial" -CommandArgs @("run", "build"); if ($InitialBuildPassed) { Write-Ok "Build inicial passou." } else { Write-Warn "Build inicial já falhava; o final será comparado." } }
    if (-not $DryRun -and -not $SkipLint -and ("lint" -in $scripts)) { $InitialLintPassed = Run-Npm -Label "lint-inicial" -CommandArgs @("run", "lint"); if ($InitialLintPassed) { Write-Ok "Lint inicial passou." } else { Write-Warn "Lint inicial já falhava." } }

    Write-Step "Aplicando escopo aprovado"
    foreach ($s in $Specs) {
        $relative = Normalize $s.path; $full = Join-Path $ProjectRoot ($relative -replace "/", "\"); $desired = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String([string]$s.content_b64)); $currentSha = if (Test-Path $full) { Get-Sha $full } else { "" }
        if ($currentSha -eq [string]$s.sha256) { continue }
        if ($DryRun) { Write-Host ("[DRY-RUN] " + $(if (Test-Path $full) { "Atualizaria " } else { "Criaria " }) + $relative) -ForegroundColor Magenta; continue }
        if (Test-Path $full) { Backup-File $relative }
        [IO.Directory]::CreateDirectory((Split-Path -Parent $full)) | Out-Null
        [IO.File]::WriteAllText($full, $desired, $Utf8NoBom)
        $ChangedFiles.Add($relative); Write-Ok ("Aplicado: " + $relative)
    }
    if ($DryRun) {
        foreach ($g in $GuardedTextPatches) { Write-Host ("[DRY-RUN] Endureceria acesso em " + $g.Path) -ForegroundColor Magenta }
        Write-Host ""; Write-Host "DryRun concluído. Nenhum arquivo foi alterado." -ForegroundColor Green; exit 0
    }

    Apply-GuardedLegacyApiPatches

    Write-Step "QA estrutural"
    if ($ChangedFiles.Count -gt 0) { & git --no-pager diff --check -- @($ChangedFiles); if ($LASTEXITCODE -ne 0) { throw "git diff --check falhou nos arquivos do patch." } }
    $platform = [IO.File]::ReadAllText((Join-Path $ProjectRoot "lib\platform-admin.ts")); $proxy = [IO.File]::ReadAllText((Join-Path $ProjectRoot "proxy.ts")); $partners = [IO.File]::ReadAllText((Join-Path $ProjectRoot "app\api\parceiros\route.ts"))
    foreach ($needle in @("OFFICIAL_PLATFORM_OWNER_EMAIL", "viniciusadm@orcaly.com", "SUPPORT_ALLOWED", "requireOfficialPlatformOwner")) { if (-not $platform.Contains($needle)) { throw "Segurança owner ausente: $needle" } }
    foreach ($needle in @("officialOwner", "activeSupport", "/suporte", "/parceiros/login")) { if (-not $proxy.Contains($needle)) { throw "Roteamento interno ausente: $needle" } }
    if (-not $partners.Contains("internalPortal")) { throw "Login via parceiros não foi integrado." }
    $affApi = [IO.File]::ReadAllText((Join-Path $ProjectRoot "app\api\admin\affiliates\route.ts"))
    $legacySummary = [IO.File]::ReadAllText((Join-Path $ProjectRoot "app\api\platform-admin\summary\route.ts"))
    if ($affApi -notmatch "requireOfficialPlatformOwner\(request\)") { throw "API administrativa de indicadores ainda aceita leitura não-owner." }
    if ($legacySummary -notmatch "requireOfficialPlatformOwner\(request\)") { throw "Resumo legado ainda aceita leitura não-owner." }
    Write-Ok "Owner exclusivo, suporte separado, APIs legadas endurecidas e login unificado validados."

    if (-not $SkipLint -and ("lint" -in $scripts)) { $finalLint = Run-Npm -Label "lint-final" -CommandArgs @("run", "lint"); if ($finalLint) { Write-Ok "Lint final passou." } elseif ($InitialLintPassed -eq $true) { throw "Lint passava antes e falhou após o patch." } else { Write-Warn "Lint final falhou, mas já falhava antes." } }
    if (-not $SkipFinalBuild -and ("build" -in $scripts)) { $finalBuild = Run-Npm -Label "build-final" -CommandArgs @("run", "build"); if ($finalBuild) { Write-Ok "Build final passou." } elseif ($InitialBuildPassed -eq $true) { throw "Build passava antes e falhou após o patch." } else { Write-Warn "Build final falhou, mas já falhava antes." } }

    Write-Step "Relatório e diff"
    [IO.File]::WriteAllText($ManifestPath, ((@($ChangedFiles) -join [Environment]::NewLine) + [Environment]::NewLine), $Utf8NoBom)
    Write-Report -Specs $Specs -Status "CONCLUÍDO"
    if ($ChangedFiles.Count -gt 0) { & git --no-pager diff -- @($ChangedFiles) }
    Write-Host ""; Write-Host ("=" * 72) -ForegroundColor Green; Write-Host " OWNER BACKOFFICE V2 APLICADO" -ForegroundColor Green; Write-Host ("=" * 72) -ForegroundColor Green
    Write-Host "Owner: viniciusadm@orcaly.com"; Write-Host "Login: /parceiros/login"; Write-Host "Painel owner: /admin"; Write-Host "Assinantes: /admin/assinantes"; Write-Host "Suporte limitado: /suporte"; Write-Host "Indicadores: /admin/indicacoes"; Write-Host "Acessos: /admin/equipe"; Write-Host ""; Write-Host ("Backup: " + $BackupRoot); Write-Host ("Relatório: " + $ReportPath); Write-Host "Nenhum commit, push, deploy ou migration foi executado." -ForegroundColor Cyan
} catch {
    Write-Host ""; Write-Host ("[ERRO] " + $_.Exception.Message) -ForegroundColor Red
    if (-not $DryRun -and $ChangedFiles.Count -gt 0) { Write-Warn "Restaurando todos os arquivos gravados por este patch."; Restore-Files; try { Write-Report -Specs $Specs -Status "FALHOU - ROLLBACK EXECUTADO" } catch {} }
    if (-not $DryRun -and (Test-Path $BackupRoot)) { Write-Host ("Diagnóstico: " + $BackupRoot) -ForegroundColor Yellow }
    exit 1
}
